$directory=Join-Path $PSScriptRoot 'marks'
New-Item -ItemType Directory -Path $directory -Force | Out-Null
foreach($mark in $marks){
 $geometry=[Windows.Media.Geometry]::Parse("F1 "+$mark.Data).Clone()
 $geometry.Transform=[Windows.Media.ScaleTransform]::new(3.75,3.75)
 $visual=[Windows.Media.DrawingVisual]::new()
 $draw=$visual.RenderOpen()
 $draw.PushTransform([Windows.Media.TranslateTransform]::new(3,3))
 $draw.DrawGeometry([Windows.Media.SolidColorBrush]::new([Windows.Media.ColorConverter]::ConvertFromString($mark.Color)),$null,$geometry)
 $draw.Close()
 $bitmap=[Windows.Media.Imaging.RenderTargetBitmap]::new(96,96,96,96,[Windows.Media.PixelFormats]::Pbgra32)
 $bitmap.Render($visual)
 $encoder=[Windows.Media.Imaging.PngBitmapEncoder]::new()
 $encoder.Frames.Add([Windows.Media.Imaging.BitmapFrame]::Create($bitmap))
 $file=[IO.File]::Create((Join-Path $directory ($mark.Name+'.png')))
 try{$encoder.Save($file)}finally{$file.Dispose()}
}